export function begin(a, b, wheelchair) {
    location.a = a
    location.b = b
    location.wheelchair = wheelchair
    for (var i of document.getElementsByTagName("canvas")) {
        i.remove()
    }
    var url = new URL(window.location)
    url.searchParams.set("origin", a)
    url.searchParams.set("target", b)
    url.searchParams.set("wheelchair", wheelchair)
    window.location.replace(url.href)
    main()
}

